import gzip,collections,csv,os
lib=list(csv.DictReader(open('/task/input/library.tsv'),delimiter='\t'))
byseq={r['sequence']:r for r in lib}
scaf='GTTTTAGAGCTA'
comp=str.maketrans('ACGTN','TGCAN')
for path in sorted(__import__('glob').glob('/task/input/fastq/*.fastq.gz')):
    total=0; mapped=0; orientations=collections.Counter(); unmatched=collections.Counter(); multimap=0
    with gzip.open(path,'rt') as fh:
        for i,line in enumerate(fh):
            if i%4: continue
            s=line.strip(); total+=1; hits=[]
            for orient,rr in (('F',s),('R',s.translate(comp)[::-1])):
                k=rr.find(scaf)
                if k>=20:
                    sp=rr[k-20:k]; r=byseq.get(sp)
                    if r: hits.append((orient,r['sgRNA']))
            if hits:
                mapped+=1; orientations[tuple(x[0] for x in hits)]+=1
                if len(hits)>1: multimap+=1
            else:
                for orient,rr in (('F',s),('R',s.translate(comp)[::-1])):
                    k=rr.find(scaf)
                    if k>=20: unmatched[(orient,rr[k-20:k],rr[max(0,k-30):k+20])]+=1
    print(os.path.basename(path),{'total':total,'mapped':mapped,'orientations':orientations.most_common(),'multi':multimap,'unmatched_context':len(unmatched),'top':unmatched.most_common(3)})
